import sys
from datetime import date, timedelta, datetime


def minutes(text):
    h, m = text.split(":")
    return int(h) * 60 + int(m)


def clock(total_minutes):
    total = total_minutes
    hours = total // 60
    minutes = total % 60
    return f"{hours:02d}:{minutes:02d}"


def parse_time(s):
    h, m = s.split(":")
    return int(h) * 60 + int(m)


def main():
    settings = {}
    busy = {}
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        parts = line.split()
        if not parts:
            continue
        if parts[0] == "busy":
            who, day_str, start_str, end_str = parts[1:]
            day = datetime.strptime(day_str, "%Y-%m-%d").date()
            start = parse_time(start_str)
            end = parse_time(end_str)
            busy.setdefault((who, day), []).append((start, end))
        else:
            settings[parts[0]] = parts[1:]
    if "days" not in settings or len(settings["days"]) != 2:
        print("Invalid input: exactly one 'days <first> <last>' line required")
        return
    if "hours" not in settings or len(settings["hours"]) != 2:
        print("Invalid input: exactly one 'hours <start> <end>' line required")
        return
    if "duration" not in settings or len(settings["duration"]) != 1:
        print("Invalid input: exactly one 'duration <minutes>' line required")
        return
    if "buffer" in settings:
        if len(settings["buffer"]) != 1:
            print("Invalid input: 'buffer <minutes>' must appear at most once")
            return
        buffer = int(settings["buffer"][0])
    else:
        buffer = 0

    first = date.fromisoformat(settings["days"][0])
    last = date.fromisoformat(settings["days"][1])
    open_at = parse_time(settings["hours"][0])
    close_at = parse_time(settings["hours"][1])
    required_duration = int(settings["duration"][0])

    day = first
    while day <= last:
        day_str = day.isoformat()
        taken = []
        if ("A", day_str) in busy:
            taken.extend(busy[("A", day_str)])
        if ("B", day_str) in busy:
            taken.extend(busy[("B", day_str)])

        # Sort busy intervals by start time
        taken.sort(key=lambda x: x[0])

        free_slots = []
        cursor = open_at

        for start, end in taken:
            if cursor < start:
                if (end - cursor) >= required_duration:
                    free_slots.append(f"{clock(cursor)}-{clock(start)}")
                cursor = end
            else:
                continue

        if (close_at - cursor) >= required_duration:
            free_slots.append(f"{clock(cursor)}-{clock(close_at)}")

        if free_slots:
            print(f"{day_str} {' '.join(free_slots)}")
        else:
            print(f"{day_str} none")

        day += timedelta(days=1)


if __name__ == "__main__":
    main()
